SET XACT_ABORT ON;
BEGIN TRANSACTION;
CREATE TABLE Core_BlobFileReference (Id bigint IDENTITY(1,1) NOT NULL PRIMARY KEY, BlobName nvarchar(1024) NOT NULL, EntityType nvarchar(100) NOT NULL, EntityId bigint NOT NULL, BlobUrl nvarchar(2048) NULL, CreatedOn datetime2 NOT NULL);
CREATE INDEX IX_Core_BlobFileReference_EntityType_EntityId ON Core_BlobFileReference(EntityType,EntityId);
CREATE TABLE Core_FarmLabSample (Id uniqueidentifier NOT NULL PRIMARY KEY, OrchardProfileId bigint NOT NULL, FarmerId bigint NOT NULL, SampleType nvarchar(16) NOT NULL, SampledAt date NOT NULL, LabName nvarchar(200) NULL, Status nvarchar(16) NOT NULL, CreatedOn datetimeoffset NOT NULL, CreatedById bigint NOT NULL, CONSTRAINT FK_Core_FarmLabSample_Orchard FOREIGN KEY (OrchardProfileId) REFERENCES Core_OrchardProfile(Id));
CREATE INDEX IX_Core_FarmLabSample_OrchardProfileId_SampleType_SampledAt ON Core_FarmLabSample(OrchardProfileId,SampleType,SampledAt);
CREATE TABLE Core_FarmLabReport (Id uniqueidentifier NOT NULL PRIMARY KEY, SampleId uniqueidentifier NOT NULL, VersionNumber int NOT NULL, Status nvarchar(16) NOT NULL, ReportedAt date NOT NULL, Source nvarchar(100) NULL, MethodNotes nvarchar(2000) NULL, SupersedesReportId uniqueidentifier NULL, CreatedOn datetimeoffset NOT NULL, CreatedById bigint NOT NULL, VerifiedAt datetimeoffset NULL, VerifiedById bigint NULL, ReviewNotes nvarchar(2000) NULL, CONSTRAINT FK_Core_FarmLabReport_Sample FOREIGN KEY(SampleId) REFERENCES Core_FarmLabSample(Id));
CREATE UNIQUE INDEX IX_Core_FarmLabReport_SampleId_VersionNumber ON Core_FarmLabReport(SampleId,VersionNumber);
CREATE TABLE Core_FarmLabReading (Id uniqueidentifier NOT NULL PRIMARY KEY, ReportId uniqueidentifier NOT NULL, AnalyteCode nvarchar(64) NOT NULL, Value decimal(18,6) NOT NULL, Unit nvarchar(32) NOT NULL, Method nvarchar(200) NULL, CONSTRAINT FK_Core_FarmLabReading_Report FOREIGN KEY(ReportId) REFERENCES Core_FarmLabReport(Id));
CREATE UNIQUE INDEX IX_Core_FarmLabReading_ReportId_AnalyteCode ON Core_FarmLabReading(ReportId,AnalyteCode);
CREATE TABLE Core_FarmLabAttachment (Id uniqueidentifier NOT NULL PRIMARY KEY, ReportId uniqueidentifier NOT NULL, BlobFileReferenceId bigint NOT NULL, FileName nvarchar(260) NOT NULL, ContentType nvarchar(100) NOT NULL, SizeBytes bigint NOT NULL, ScanStatus nvarchar(16) NOT NULL, CreatedOn datetimeoffset NOT NULL, CONSTRAINT FK_Core_FarmLabAttachment_Report FOREIGN KEY(ReportId) REFERENCES Core_FarmLabReport(Id), CONSTRAINT FK_Core_FarmLabAttachment_Blob FOREIGN KEY(BlobFileReferenceId) REFERENCES Core_BlobFileReference(Id));
CREATE UNIQUE INDEX IX_Core_FarmLabAttachment_ReportId_BlobFileReferenceId ON Core_FarmLabAttachment(ReportId,BlobFileReferenceId);
CREATE TABLE Core_FarmNutrientRangeRule (Id uniqueidentifier NOT NULL PRIMARY KEY, Version uniqueidentifier NOT NULL, AnalyteCode nvarchar(64) NOT NULL, Crop nvarchar(100) NULL, Variety nvarchar(100) NULL, GrowthStage nvarchar(100) NULL, Unit nvarchar(32) NOT NULL, Minimum decimal(18,6) NULL, Maximum decimal(18,6) NULL, Status nvarchar(16) NOT NULL, Evidence nvarchar(2000) NULL, CreatedOn datetimeoffset NOT NULL, CreatedById bigint NOT NULL, ApprovedOn datetimeoffset NULL, ApprovedById bigint NULL);
CREATE INDEX IX_Core_FarmNutrientRangeRule_AnalyteCode_Status ON Core_FarmNutrientRangeRule(AnalyteCode,Status);
COMMIT TRANSACTION;
